package com.smartgrading.backend.controller;
import com.smartgrading.backend.dto.*; import com.smartgrading.backend.service.ClassService; import jakarta.validation.Valid; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/classes") public class ClassController { private final ClassService service; public ClassController(ClassService s){service=s;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public ClassResponse create(@Valid @RequestBody ClassRequest r){return service.create(r);} @GetMapping public List<ClassResponse> all(){return service.all();} @GetMapping("/{id}") public ClassResponse get(@PathVariable Integer id){return service.get(id);} @PutMapping("/{id}") public ClassResponse update(@PathVariable Integer id,@Valid @RequestBody ClassRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Integer id){service.delete(id);} @PostMapping("/{classId}/students/{studentId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void add(@PathVariable Integer classId,@PathVariable Integer studentId){service.addStudent(classId,studentId);} @DeleteMapping("/{classId}/students/{studentId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void remove(@PathVariable Integer classId,@PathVariable Integer studentId){service.removeStudent(classId,studentId);} @GetMapping("/{classId}/students") public List<UserResponse> students(@PathVariable Integer classId){return service.students(classId);} }
